async function init(){
  try{
    const [info,catalogue]=await Promise.all([
      api('/api/overview'),api('/api/questions?view=included'),progress.open(),
    ]);
    asAvailable=info.available_banks?.includes('9702-as')===true;
    if(asAvailable&&!new URLSearchParams(location.search).has('bank')&&progress.preferences.bank!==pageBank){
      openOfflineBank(progress.preferences.bank,true);
      return;
    }
    paintPreferences();
    if(!info.syllabus)return;
    if(asPage){
      $('progress-label').textContent='学习进度 · 章节正确率';
      $('accuracy-chart').setAttribute('aria-label','AS 章节正确率雷达图');
      $('igcse-intro').textContent='用原创样题试用两套物理练习界面';
      $('paper-count').value=Math.min(catalogue.items.length,40);
      $('paper-minutes').value=Math.ceil(Number($('paper-count').value)*75/40);
    }
    allQuestions=catalogue.items;
    syllabusSections=new Map(Object.keys(info.chapters).sort().map(code=>[code,topicSummary(info.chapter_titles[code])]));
    sectionsById=new Map(allQuestions.map(item=>{
      const prefix=item.primary_objective?.match(/^\d+\.\d+(?=\.|$)/)?.[0];
      return [item.question_id,syllabusSections.has(prefix)?prefix:null];
    }));
    for(const code of sectionsById.values())if(code)sectionSizes.set(code,(sectionSizes.get(code)||0)+1);
    for(const [id,key] of [['stat-included','included'],['stat-skipped','skipped'],['included-count','included'],['skipped-count','skipped']])$(id).textContent=info[key];
    $('syllabus-version').textContent=info.syllabus.version_label.replace('-','–');
    for(const [code,count] of Object.entries(info.chapters)){const option=document.createElement('option');option.value=code;option.textContent=`${code} ${info.chapter_titles[code]||''}（${count}题）`;$('chapter-filter').append(option);}
    buildRandomRanges(info.chapters,info.chapter_titles);
    for(const year of info.years){const option=document.createElement('option');option.value=year;option.textContent=year+'年';$('year-filter').append(option);}
    state.selected=progress.lastId;
    studyController=createStudyController();
    paintProgress();updateViewButtons();await loadList({remember:false});
    const selected=$('row-'+state.selected);
    if(selected){
      const list=$('question-list');
      const needed=selected.getBoundingClientRect().bottom-list.getBoundingClientRect().bottom;
      if(needed>0)list.scrollTop+=needed;
    }
  }catch(error){$('question-title').textContent='暂时无法载入资料';toast(error.message);}
}
init();
